class AutomationScheduleConfig(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
        populate_by_name=True,
    )
    catchup_window_seconds: int | None = Field(
        900,
        alias='catchupWindowSeconds',
        description='Maximum age of a missed occurrence eligible for catch-up. Defaults to 900.',
        ge=10,
        le=31622400,
    )
    cron: str = Field(
        ..., description='Five-field POSIX cron expression.', max_length=256, min_length=1
    )
    end_at: datetime | None = Field(
        None, alias='endAt', description='Optional inclusive schedule end.'
    )
    jitter_seconds: int | None = Field(
        10,
        alias='jitterSeconds',
        description='Maximum deterministic occurrence jitter in seconds. Defaults to 10; zero disables jitter.',
        ge=0,
        le=540,
    )
    overlap_policy: (
        Literal['skip', 'buffer_one', 'buffer_all', 'allow_all', 'cancel_other'] | None
    ) = Field('skip', alias='overlapPolicy', description='Behavior when an earlier occurrence is still running. Defaults to skip.')
    start_at: datetime | None = Field(
        None, alias='startAt', description='Optional inclusive schedule start.'
    )
    timezone: str = Field(
        ...,
        description='IANA timezone used to interpret the cron expression.',
        max_length=256,
        min_length=1,
    )


