class AutomationSlackTrigger(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
        populate_by_name=True,
    )
    allow_shared_channels: bool | None = Field(
        False,
        alias='allowSharedChannels',
        description='Explicitly allow events from Slack Connect channels shared with other organizations. Defaults to false.',
    )
    bot_events: AutomationSlackBotEvents = Field(
        ..., alias='botEvents', description='Explicit external-bot policy.'
    )
    continuation: Literal['new_session', 'resume_thread'] | None = Field(
        'new_session',
        description="When resume_thread, a later matching post in the same Slack thread is delivered to the thread's existing session instead of starting a new one. Defaults to new_session. Every Slack trigger of one automation must use the same value.",
    )
    enabled: bool = Field(
        ..., description='Whether this trigger may admit runs while the automation is active.'
    )
    event_source_id: UUID = Field(
        ..., alias='eventSourceId', description='Compatible Slack Events API source.'
    )
    events: list[Literal['message', 'app_mention']] = Field(
        ...,
        description='Slack event types that may match this trigger. Only newly posted messages match; edits and deletions never start runs.',
        max_length=2,
        min_length=1,
    )
    filters: AutomationSlackFilters | None = Field(
        None, description='Optional conditions on the message. Omit to match every routed event.'
    )
    first_response: Literal['none', 'platform'] | None = Field(
        'none',
        alias='firstResponse',
        description='When platform, the platform posts an acknowledgement, a reaction and a live status line in the thread while the agent works. Defaults to none. Every Slack trigger of one automation must use the same value.',
    )
    routing: AutomationSlackRouting = Field(..., description='Workspace and channel constraints.')
    trigger_id: UUID = Field(
        ..., alias='triggerId', description='Caller-generated stable trigger identifier.'
    )
    type: Literal['slack'] = Field(..., description='Slack trigger discriminant.')


