class ConnectionProbe(BaseModel):
    model_config = ConfigDict(
        extra='forbid',
        populate_by_name=True,
    )
    activated: bool | None = Field(
        None,
        description='True when this probe moved a pending connection to active by proving its trust with a successful mint. Omitted (false) on every later probe of the same connection.',
    )
    excess_permissions: list[str] | None = Field(
        None,
        alias='excessPermissions',
        description='GitHub installation permissions above the launch App contract. Reported, not enforced: reduce the App permissions in GitHub and have installation owners approve the update.',
    )
    failure: str | None = Field(
        None,
        description='Human-readable reason the probe did not succeed, such as a suspended install or a rejected mint. Empty when ok is true.',
    )
    missing_permissions: list[str] | None = Field(
        None,
        description="Permissions this service requires that the install has not granted at the required level. Reported, not enforced: accept the provider's pending permission request to clear them.",
    )
    ok: bool = Field(
        ...,
        description='True only when the connection is active at the provider and a scoped token was successfully minted during this probe. False means the connection cannot currently be used; read failure for why. A probe that fails this way is still an HTTP 200.',
    )
    resource_count: int = Field(
        ...,
        description='Number of provider resources the connection can authorize, for example selected GitHub repositories. The live probe credential may be narrower when the provider cannot represent the entire connection scope in one token. Zero when no token could be minted.',
        ge=-9007199254740991,
        le=9007199254740991,
    )
    state: str = Field(
        ...,
        description='Lifecycle of the connection as of this probe: pending (registered, waiting for the customer to grant trust), active (usable), suspended (paused at the provider), or revoked (uninstalled or deleted). Refreshed here, so it can differ from the previously stored value: a pending connection whose trust proved usable is reported active.',
    )
    token_minted: bool = Field(
        ...,
        description='Whether a scoped credential could actually be issued during this probe. This is the check that predicts whether a session using the connection will work.',
    )


